import {
    filterHasField
} from "../../../../filter_builder/utils";
import {
    getColumnIdentifier
} from "../utils";
export const filterSyncColumnHeadersViewExtender = Base => class extends Base {
    init() {
        this.filterController = this.getController("filter");
        super.init()
    }
    optionChanged(args) {
        if ("filterValue" === args.name) {
            this._updateHeaderFilterIndicators()
        } else {
            super.optionChanged(args)
        }
    }
    _isHeaderFilterEmpty(column) {
        if (this.filterController.isFilterSyncActive()) {
            return !filterHasField(this.option("filterValue"), getColumnIdentifier(column))
        }
        return super._isHeaderFilterEmpty(column)
    }
    _needUpdateFilterIndicators() {
        return !this.filterController.isFilterSyncActive()
    }
};
